    void open(StudyStore.Row book,boolean speech){job(()->{try(StudyStore store=new StudyStore(a)){if(store.get("materials",book.id())==null)throw new IllegalStateException("Livro indisponível.");store.save("materials",book.id(),StudyStore.values("updated",System.currentTimeMillis()));}a.ui(()->{Uri uri=StudyFileProvider.uri(a,book.id());a.startActivity(new Intent(a,ReaderActivity.class).setDataAndType(uri,book.s("mime")).putExtra("name",book.s("name")).putExtra("study_title",book.s("title")).putExtra("study_path",tr("Livros")).putExtra("study_material",book.id()).putExtra("full_screen",true).putExtra("open_speech",speech));});});}
