    void deleteBook(StudyStore.Row row){if(cleaning||a.studies!=null&&a.studies.importing.get()){a.toast("Aguarde o fim da operação actual.");return;}a.dialog().setTitle("Eliminar este livro?").setMessage("Remove este livro da estante e as ligações dos módulos que partilham esta cópia. As notas dos Estudos são conservadas. O ficheiro original fora do Seeky não é apagado.").setPositiveButton("Eliminar",(d,w)->job(()->{try(StudyStore store=new StudyStore(a)){BookRemoval.Result result=BookRemoval.remove(a,store,row.id(),row.s("path"),row.s("hash"));if(store.count("materials","hash=?",new String[]{row.s("hash")})==0){Set<String> hashes=favorites();hashes.remove(row.s("hash"));prefs.edit().putStringSet("favorites",hashes).apply();}StudyEvents.changed();CloudJobs.schedule(a);a.ui(()->{reload();a.toast(result.warning.isEmpty()?"Livro eliminado. Originais conservados.":result.warning);});}catch(java.io.IOException error){throw new IllegalStateException(error.getMessage(),error);}})).setNegativeButton("Cancelar",null).show();}
    void setProgress(StudyStore.Row row,int value){job(()->{List<Long> ids=new ArrayList<>();try(StudyStore store=new StudyStore(a)){try(android.database.Cursor refs=store.getReadableDatabase().query("materials",new String[]{"id"},"path=? AND hash=?",new String[]{row.s("path"),row.s("hash")},null,null,null)){while(refs.moveToNext())ids.add(refs.getLong(0));}store.getWritableDatabase().update("materials",StudyStore.values("progress",value,"status",value==100?"Concluído":value==0?"Por estudar":"A estudar","updated",System.currentTimeMillis()),"path=? AND hash=?",new String[]{row.s("path"),row.s("hash")});}if(value==0){SharedPreferences reader=a.getSharedPreferences("seeky",0);SharedPreferences.Editor edit=reader.edit();Map<String,?> all=reader.getAll();for(long id:ids){String uri=StudyFileProvider.uri(a,id).toString();edit.putInt("reader_page_"+uri,0).putInt("reader_chapter_"+uri,0).putInt("reader_offset_"+uri,0);for(String key:all.keySet())if(key.startsWith("reader_scroll_"+uri+":"))edit.remove(key);edit.remove("speech_part_"+uri).remove("speech_offset_"+uri).remove("speech_digest_"+uri);}edit.apply();}StudyEvents.changed();CloudJobs.schedule(a);a.ui(this::reload);});}
    void progress(StudyStore.Row row){EditText value=new EditText(a);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);value.setText(row.s("progress"));a.dialog().setTitle("Progresso de leitura").setMessage("Percentagem de 0 a 100").setView(value).setPositiveButton("Guardar",(d,w)->{try{int percent=Integer.parseInt(value.getText().toString());if(percent<0||percent>100)throw new IllegalArgumentException();setProgress(row,percent);}catch(Exception e){a.toast(tr("Use 0 a 100."));}}).setNegativeButton("Cancelar",null).show();}
