    void save(){prefs.edit().putInt("layout",mode).putInt("states",mask).putInt("format",type).putInt("sort",sort).apply();}
    void menu(){UiPanel panel=new UiPanel(a,"Livros",null,"book");panel.action("add","Importar livros",null,false,this::pick);panel.action("folder","Importar pasta e subpastas",null,false,()->ImportWork.pickFolder(a,true));panel.action("clock","Tarefas em segundo plano",null,false,()->TaskService.open(a));panel.action("search","Pesquisar no conteúdo",null,false,()->LibrarySearchActivity.open(a));panel.action("edit","Editar livros em lote",null,false,()->a.startActivity(new Intent(a,LibraryBatchActivity.class)));panel.action("refresh","Verificar e remover duplicados",null,false,this::duplicates);panel.action("document","Relatório de importação",null,false,()->a.studies.showImportReport());panel.action("folder","Colecções e grupos",null,false,()->BookCategories.choose(this));panel.action("filters","Ordenar e filtrar",null,false,this::filters);panel.action("refresh","Reconstruir capas",null,false,()->{a.thumbnails.trim();draw();});panel.action("book","Abrir um livro desta página",null,false,()->{if(!books.isEmpty())open(books.get(new Random().nextInt(books.size())),false);});panel.show();}
    void duplicates(){if(cleaning||a.studies.importing.get()){a.toast("Aguarde o fim da importação ou verificação actual.");return;}cleaning=true;java.util.concurrent.atomic.AtomicBoolean stop=new java.util.concurrent.atomic.AtomicBoolean();TextView status=a.label("A verificar cópias privadas…",14,a.text);AlertDialog dialog=a.dialog().setTitle("Duplicados da biblioteca").setView(status).setNegativeButton("Cancelar",(d,w)->stop.set(true)).create();dialog.setOnCancelListener(d->stop.set(true));dialog.show();final java.util.concurrent.atomic.AtomicBoolean pending=new java.util.concurrent.atomic.AtomicBoolean();final long[] last={0};job(()->{try(StudyStore store=new StudyStore(a)){BookDuplicates.Result result=BookDuplicates.clean(a,store,()->stop.get()||closed||a.dead,name->{long now=android.os.SystemClock.elapsedRealtime();if(now-last[0]<200||!pending.compareAndSet(false,true))return;last[0]=now;a.ui(()->{status.setText(tr("A verificar")+" · "+StudyImporter.safe(name,120));pending.set(false);});});StudyEvents.changed();CloudJobs.schedule(a);a.ui(()->{dialog.dismiss();reload();a.dialog().setTitle("Verificação concluída").setMessage(result.summary()).setPositiveButton("Concluir",null).show();});}catch(Exception e){a.ui(()->{dialog.dismiss();a.showError(e);});}finally{cleaning=false;}});}
